CREATE OR REPLACE FUNCTION public.app_admin_prep_import_questions_json(p_questions jsonb, p_concours_type text DEFAULT NULL::text, p_subject_name text DEFAULT NULL::text, p_subject_id uuid DEFAULT NULL::uuid, p_source text DEFAULT 'admin_import'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_uid uuid;
    v_count integer := 0;
    v_skipped integer := 0;
    v_errors text[] := '{}';
    v_q jsonb;
    v_subject_id uuid;
    v_question_id uuid;
    v_options jsonb;
    v_correct_index integer;
    v_content text;
    v_difficulty integer;
    v_explanation text;
    v_question_type text;
    i integer;
BEGIN
    v_uid := auth.uid();
    IF v_uid IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Vous devez être connecté pour importer des questions.');
    END IF;

    IF p_questions IS NULL OR jsonb_array_length(p_questions) = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Le tableau de questions est vide.');
    END IF;

    -- Résoudre le subject_id
    IF p_subject_id IS NOT NULL THEN
        v_subject_id := p_subject_id;
    ELSIF p_subject_name IS NOT NULL THEN
        SELECT id INTO v_subject_id
        FROM app.prep_subjects
        WHERE LOWER(title) = LOWER(p_subject_name)
        LIMIT 1;

        -- Auto-créer le sujet s'il n'existe pas
        IF v_subject_id IS NULL THEN
            INSERT INTO app.prep_subjects (slug, title)
            VALUES (
                LOWER(REPLACE(REPLACE(TRIM(p_subject_name), ' ', '-'), '''', '')),
                TRIM(p_subject_name)
            )
            RETURNING id INTO v_subject_id;
        END IF;
    END IF;

    -- Si toujours NULL, créer un sujet par défaut
    IF v_subject_id IS NULL THEN
        SELECT id INTO v_subject_id
        FROM app.prep_subjects
        WHERE LOWER(title) = 'culture générale'
        LIMIT 1;

        IF v_subject_id IS NULL THEN
            INSERT INTO app.prep_subjects (slug, title)
            VALUES ('culture-generale', 'Culture Générale')
            RETURNING id INTO v_subject_id;
        END IF;
    END IF;

    FOR i IN 0..jsonb_array_length(p_questions) - 1 LOOP
        BEGIN
            v_q := p_questions->i;

            -- Accepter plusieurs clés
            v_content := COALESCE(
                v_q->>'question',
                v_q->>'content',
                v_q->>'enonce',
                v_q->>'texte',
                ''
            );

            IF v_content = '' OR LENGTH(TRIM(v_content)) < 5 THEN
                v_skipped := v_skipped + 1;
                v_errors := array_append(v_errors,
                    format('Question %s : texte manquant ou trop court', i + 1));
                CONTINUE;
            END IF;

            v_options := v_q->'options';
            IF v_options IS NULL OR jsonb_typeof(v_options) != 'array' THEN
                v_options := '[]'::jsonb;
            END IF;

            v_correct_index := COALESCE((v_q->>'correct_index')::integer, (v_q->>'reponse_correcte')::integer, 0);

            v_difficulty := COALESCE((v_q->>'difficulty')::integer, (v_q->>'difficulte')::integer, 2);
            IF v_difficulty < 1 THEN v_difficulty := 1; END IF;
            IF v_difficulty > 5 THEN v_difficulty := 5; END IF;

            v_explanation := COALESCE(v_q->>'explanation', v_q->>'explication', v_q->>'correction');

            v_question_type := COALESCE(v_q->>'question_type', v_q->>'type', 'mcq');

            INSERT INTO app.prep_questions (
                subject_id, question, content, options, correct_index,
                explanation, difficulty, subject, concours_type,
                source, is_published, is_active, question_type
            ) VALUES (
                v_subject_id,
                TRIM(v_content),
                TRIM(v_content),
                v_options,
                v_correct_index,
                v_explanation,
                v_difficulty,
                COALESCE(p_subject_name, v_q->>'subject', v_q->>'matiere', 'Culture Générale'),
                p_concours_type,
                p_source,
                true,
                true,
                v_question_type
            ) RETURNING id INTO v_question_id;

            v_count := v_count + 1;

        EXCEPTION WHEN OTHERS THEN
            v_skipped := v_skipped + 1;
            v_errors := array_append(v_errors,
                format('Question %s : %s', i + 1, SQLERRM));
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'success', v_count > 0,
        'imported_count', v_count,
        'skipped_count', v_skipped,
        'total', jsonb_array_length(p_questions),
        'source', p_source,
        'subject_id', v_subject_id,
        'errors', to_jsonb(v_errors)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_admin_prep_import_text_bulk(p_text text, p_concours_type text DEFAULT NULL::text, p_subject_name text DEFAULT NULL::text, p_doc_type text DEFAULT 'sujet'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_uid uuid;
    v_subject_id uuid;
    v_doc_id uuid;
    v_chunks_count integer := 0;
    v_offset integer;
    v_idx integer;
BEGIN
    v_uid := auth.uid();
    IF v_uid IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Vous devez être connecté pour indexer du contenu.');
    END IF;

    IF p_text IS NULL OR LENGTH(TRIM(p_text)) < 20 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Le texte est trop court (minimum 20 caractères).');
    END IF;

    -- Résoudre le subject_id
    IF p_subject_name IS NOT NULL THEN
        SELECT id INTO v_subject_id
        FROM app.prep_subjects
        WHERE LOWER(title) = LOWER(p_subject_name)
        LIMIT 1;
    END IF;

    -- Créer le document source (colonne = created_by, PAS uploaded_by)
    INSERT INTO app.prep_source_documents (
        created_by, subject_id, year, doc_type,
        source_type, extracted_text, concours_type, status
    ) VALUES (
        v_uid, v_subject_id, EXTRACT(YEAR FROM now())::integer,
        p_doc_type, 'text_paste', p_text, p_concours_type, 'indexed'
    ) RETURNING id INTO v_doc_id;

    -- Premier chunk
    INSERT INTO app.prep_doc_chunks (
        source_document_id, chunk_index, content,
        chunk_type, concours_type, subject_name, token_count
    ) VALUES (
        v_doc_id, 0, LEFT(p_text, 4000),
        p_doc_type, p_concours_type, p_subject_name,
        CEIL(LENGTH(p_text) / 4.0)::integer
    );
    v_chunks_count := 1;

    IF LENGTH(p_text) > 4000 THEN
        v_offset := 4000;
        v_idx := 1;
        WHILE v_offset < LENGTH(p_text) LOOP
            INSERT INTO app.prep_doc_chunks (
                source_document_id, chunk_index, content,
                chunk_type, concours_type, subject_name, token_count
            ) VALUES (
                v_doc_id, v_idx, SUBSTR(p_text, v_offset + 1, 4000),
                p_doc_type, p_concours_type, p_subject_name,
                LEAST(1000, CEIL((LENGTH(p_text) - v_offset) / 4.0))::integer
            );
            v_offset := v_offset + 4000;
            v_idx := v_idx + 1;
            v_chunks_count := v_chunks_count + 1;
        END LOOP;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'document_id', v_doc_id,
        'text_length', LENGTH(p_text),
        'chunks_count', v_chunks_count,
        'doc_type', p_doc_type,
        'message', 'Texte indexé avec succès (' || v_chunks_count || ' chunk(s), ' || LENGTH(p_text) || ' caractères).'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_prep_get_adaptive_quiz(p_count integer DEFAULT 10, p_concours_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_student_id uuid;
    v_questions jsonb := '[]'::jsonb;
    v_has_weaknesses boolean;
    v_weakness_questions integer;
    v_regular_questions integer;
BEGIN
    v_student_id := auth.uid();
    IF v_student_id IS NULL THEN
        RAISE EXCEPTION 'Non authentifié';
    END IF;

    SELECT EXISTS(
        SELECT 1 FROM app.prep_student_weaknesses
        WHERE student_id = v_student_id AND needs_practice = true
    ) INTO v_has_weaknesses;

    IF v_has_weaknesses THEN
        v_weakness_questions := GREATEST(1, CEIL(p_count * 0.7));
        v_regular_questions := p_count - v_weakness_questions;
    ELSE
        v_weakness_questions := 0;
        v_regular_questions := p_count;
    END IF;

    -- Questions ciblées sur les faiblesses
    IF v_weakness_questions > 0 THEN
        WITH weak_subjects AS (
            SELECT subject_id, priority_weight, recommended_difficulty
            FROM app.prep_student_weaknesses
            WHERE student_id = v_student_id AND needs_practice = true
            ORDER BY priority_weight DESC, weakness_score DESC
            LIMIT 5
        ),
        weakness_pool AS (
            SELECT DISTINCT ON (q.id)
                q.id, q.question, q.content, q.options,
                q.correct_index, q.explanation, q.difficulty,
                q.subject, q.subject_id, q.image_url,
                w.priority_weight,
                RANDOM() AS rand
            FROM app.prep_questions q
            JOIN weak_subjects w ON w.subject_id = q.subject_id
            WHERE q.is_published = true AND q.is_active = true
              AND (p_concours_type IS NULL OR q.concours_type = p_concours_type)
        )
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', id, 'question', question, 'content', content,
                'options', options, 'correct_index', correct_index,
                'explanation', explanation, 'difficulty', difficulty,
                'subject', subject, 'subject_id', subject_id,
                'image_url', image_url, 'is_weakness_targeted', true
            ) ORDER BY priority_weight DESC, rand
        ), '[]'::jsonb) INTO v_questions
        FROM (SELECT * FROM weakness_pool LIMIT v_weakness_questions) t;
    END IF;

    -- Compléter avec questions générales
    IF v_regular_questions > 0 THEN
        WITH excluded_ids AS (
            SELECT (value->>'id')::uuid AS id
            FROM jsonb_array_elements(COALESCE(v_questions, '[]'::jsonb))
        ),
        regular_pool AS (
            SELECT q.id, q.question, q.content, q.options,
                   q.correct_index, q.explanation, q.difficulty,
                   q.subject, q.subject_id, q.image_url
            FROM app.prep_questions q
            WHERE q.is_published = true AND q.is_active = true
              AND (p_concours_type IS NULL OR q.concours_type = p_concours_type)
              AND q.id NOT IN (SELECT id FROM excluded_ids)
            ORDER BY RANDOM()
            LIMIT v_regular_questions
        )
        SELECT COALESCE(v_questions, '[]'::jsonb) || COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', id, 'question', question, 'content', content,
                'options', options, 'correct_index', correct_index,
                'explanation', explanation, 'difficulty', difficulty,
                'subject', subject, 'subject_id', subject_id,
                'image_url', image_url, 'is_weakness_targeted', false
            )
        ), '[]'::jsonb) INTO v_questions
        FROM regular_pool;
    END IF;

    -- Mélanger
    WITH shuffled AS (
        SELECT value FROM jsonb_array_elements(COALESCE(v_questions, '[]'::jsonb)) AS value
        ORDER BY RANDOM()
    )
    SELECT COALESCE(jsonb_agg(value), '[]'::jsonb) INTO v_questions FROM shuffled;

    RETURN jsonb_build_object(
        'adaptive_mode', v_has_weaknesses,
        'weakness_ratio', CASE WHEN p_count > 0 THEN v_weakness_questions::decimal / p_count ELSE 0 END,
        'total_questions', jsonb_array_length(COALESCE(v_questions, '[]'::jsonb)),
        'questions', COALESCE(v_questions, '[]'::jsonb)
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.app_prep_get_rag_chunks(p_subject_id uuid, p_limit integer DEFAULT 12, p_max_chars integer DEFAULT 6000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID := auth.uid();
  v_limit INTEGER := GREATEST(1, LEAST(COALESCE(p_limit, 12), 30));
  v_max_chars INTEGER := GREATEST(200, LEAST(COALESCE(p_max_chars, 6000), 20000));
  v_chunks JSONB;
  v_chunks_text TEXT;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'not_authenticated');
  END IF;

  -- Paywall / entitlement
  IF NOT app_has_feature_access('prep_concours') THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'no_feature_access');
  END IF;

  IF p_subject_id IS NULL THEN
    RETURN JSONB_BUILD_OBJECT('success', FALSE, 'error', 'missing_subject_id');
  END IF;

  -- On récupère des chunks liés à des documents "utilisables".
  -- Statuts acceptés: indexed / validated / published.
  SELECT COALESCE(
    JSONB_AGG(
      JSONB_BUILD_OBJECT(
        'title', CONCAT('Doc ', LEFT(x.doc_id::TEXT, 8), ' • chunk ', x.chunk_index::TEXT),
        'content', x.content
      )
    ),
    '[]'::JSONB
  )
  INTO v_chunks
  FROM (
    SELECT d.id AS doc_id,
           d.updated_at AS doc_updated_at,
           c.chunk_index,
           c.content
    FROM app.prep_doc_chunks c
    JOIN app.prep_source_documents d
      ON d.id = c.source_document_id
    WHERE d.subject_id = p_subject_id
      AND d.status IN ('indexed', 'validated', 'published')
    ORDER BY d.updated_at DESC, c.chunk_index ASC
    LIMIT v_limit
  ) x;

  v_chunks_text := COALESCE(v_chunks::TEXT, '[]');

  RETURN JSONB_BUILD_OBJECT(
    'success', TRUE,
    'chunks', COALESCE(v_chunks, '[]'::JSONB),
    'truncated', (LENGTH(v_chunks_text) > v_max_chars)
  );
END;
$function$
